// NewSaveStackRequestBody builds the HTTP request body from the payload of the
// "saveStack" endpoint of the "onboarding" service.
func NewSaveStackRequestBody(p *onboarding.SaveStackPayload) *SaveStackRequestBody {
	body := &SaveStackRequestBody{
		MdmVendor: p.MdmVendor,
	}
	if p.Providers != nil {
		body.Providers = make([]*OnboardingSelectedProviderRequestBody, len(p.Providers))
		for i, val := range p.Providers {
			if val == nil {
				body.Providers[i] = nil
				continue
			}
			body.Providers[i] = marshalOnboardingOnboardingSelectedProviderToOnboardingSelectedProviderRequestBody(val)
		}
	} else {
		body.Providers = []*OnboardingSelectedProviderRequestBody{}
	}
	if p.ProductSlugs != nil {
		body.ProductSlugs = make([]string, len(p.ProductSlugs))
		for i, val := range p.ProductSlugs {
			body.ProductSlugs[i] = val
		}
	} else {
		body.ProductSlugs = []string{}
	}
	return body
}

